INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'A blend recipe calls for 70% cotton and 30% viscose by weight for a total blend batch of 1,500 kg. How many kg of viscose fiber are needed?', '["450 kg","1,050 kg","700 kg","300 kg"]'::jsonb, '450 kg', 'Viscose weight = 30% of total = 0.30 × 1,500 kg = 450 kg.', 1, '{"blend-ratio-calc"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'A blend recipe calls for 50% cotton and 50% polyester by weight for a total blend batch of 3,000 kg. How many kg of each fiber are needed?', '["1,500 kg each","1,000 kg and 2,000 kg","2,000 kg and 1,000 kg","3,000 kg and 0 kg"]'::jsonb, '1,500 kg each', 'Each fiber = 50% of total = 0.50 × 3,000 kg = 1,500 kg for both cotton and polyester.', 1, '{"blend-ratio-calc"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A yarn is required at 34s Ne. If it''s made by plying two equal singles together, what approximate single yarn count should each single be spun to?', '["68s Ne","34s Ne","17s Ne","0.5s Ne"]'::jsonb, '68s Ne', 'Resultant ply count ≈ single count ÷ number of plies, so single count = resultant count × number of plies = 34 × 2 = 68s Ne — each single must be spun finer (a higher Ne number) than the target resultant, since plying combines them into a coarser final yarn.', 2, '{"ply-count-reverse-calc"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A comber''s noil percentage is 20%. If a mill wants to produce 800 kg of combed (net) fiber, approximately how much input lap fiber must be fed into the comber?', '["≈ 1,000 kg","≈ 960 kg","≈ 800 kg","≈ 640 kg"]'::jsonb, '≈ 1,000 kg', 'Input needed = desired output ÷ (1 − noil%) = 800 ÷ (1 − 0.20) = 800 ÷ 0.80 = 1,000 kg.', 2, '{"comber-input-calc"}'::text[]);
